 const atom=r.atoms[params.atom],hits=r.matches[params.pattern]||[],key=params.stereo?'canonical':'without_stereo';
 const group=rows.filter(x=>x[key]===r[key]).map(x=>x.id),unique=new Set(rows.map(x=>x[key])).size;
 const frame=document.createElement('div');frame.innerHTML=r.drawings[params.pattern]||r.drawings.none;
 const svg=frame.querySelector('svg');svg.removeAttribute('width');svg.removeAttribute('height');svg.setAttribute('viewBox','0 0 640 360');svg.setAttribute('role','img');svg.setAttribute('aria-label',r[zh?'zh':'en']);
